var OWN_TOOLS = {
  mail_envoyer: "Envoyer un e-mail",
  mail_chercher: "Recherche dans Gmail",
  mail_lire: "Lecture d\u2019un e-mail",
  mail_brouillon: "Brouillon dans Gmail"
};
var VERBS = {
  create: "Cr\xE9er",
  add: "Ajouter",
  new: "Cr\xE9er",
  update: "Modifier",
  edit: "Modifier",
  delete: "Supprimer",
  remove: "Retirer",
  send: "Envoyer",
  get: "Lire",
  read: "Lire",
  list: "Lister",
  search: "Chercher",
  find: "Chercher",
  duplicate: "Dupliquer",
  convert: "Convertir",
  validate: "Valider",
  cancel: "Annuler",
  archive: "Archiver"
};
var NOUNS = {
  quote: "devis",
  quotes: "devis",
  estimate: "devis",
  estimates: "devis",
  invoice: "facture",
  invoices: "factures",
  customer: "client",
  customers: "clients",
  client: "client",
  clients: "clients",
  contact: "contact",
  contacts: "contacts",
  product: "article",
  products: "articles",
  item: "article",
  items: "articles",
  article: "article",
  articles: "articles",
  line: "ligne",
  lines: "lignes",
  site: "chantier",
  sites: "chantiers",
  job: "chantier",
  jobs: "chantiers",
  intervention: "intervention",
  interventions: "interventions",
  project: "chantier",
  projects: "chantiers",
  by: "par",
  email: "e-mail",
  to: "en",
  pdf: "PDF"
};
var words = (s5) => s5.replace(/([a-z])([A-Z])/g, "$1_$2").toLowerCase().split(/[_.\s-]+/).filter(Boolean);
var cap = (s5) => s5.charAt(0).toUpperCase() + s5.slice(1);
function toolLabel(name4) {
  if (OWN_TOOLS[name4]) return OWN_TOOLS[name4];
  const w = words(name4);
  if (!w.length) return name4;
  const [first2, ...rest] = w;
  const verb = VERBS[first2];
  const tail = rest.map((x) => NOUNS[x] ?? x).join(" ");
  return verb ? `${verb}${tail ? ` ${tail}` : ""}` : cap(w.map((x) => NOUNS[x] ?? x).join(" "));
}

