// server/config.ts
import { readFileSync } from "node:fs";
import { createHash as createHash3 } from "node:crypto";
function commitFile() {
  try {
    const v = readFileSync(new URL("./COMMIT", import.meta.url), "utf8").trim();
    return /^[0-9a-f]{7,40}$/.test(v) ? v : null;
  } catch {
    return null;
  }
}
function loadConfig(env = process.env) {
  const publicUrl = (env.PUBLIC_URL ?? "http://localhost:5173").replace(/\/+$/, "");
  const raw2 = env.ENVO_SECRET_KEY?.trim();
  if (!raw2 && publicUrl.startsWith("https://")) throw new Error("ENVO_SECRET_KEY manquante : refus de d\xE9marrer en production sans cl\xE9 de chiffrement");
  const secretKey = createHash3("sha256").update(raw2 || "envo-dev-uniquement").digest();
  const effort = env.ANTHROPIC_EFFORT === "low" || env.ANTHROPIC_EFFORT === "high" ? env.ANTHROPIC_EFFORT : "medium";
  const anthropic = env.ANTHROPIC_API_KEY?.trim() ? { apiKey: env.ANTHROPIC_API_KEY.trim(), model: env.ANTHROPIC_MODEL?.trim() || "claude-opus-5-5", overviewModel: env.ANTHROPIC_MODEL_TABLEAU?.trim() || "claude-sonnet-5-5", effort } : null;
  const mail = env.MAILJET_API_KEY && env.MAILJET_SECRET_KEY && env.MAIL_FROM ? { apiKey: env.MAILJET_API_KEY, secretKey: env.MAILJET_SECRET_KEY, from: env.MAIL_FROM, fromName: env.MAIL_FROM_NAME || "Envo" } : null;
  return {
    publicUrl,
    port: Number(env.PORT ?? 3880),
    commit: env.ENVO_COMMIT ?? commitFile() ?? "dev",
    secretKey,
    anthropic,
    mail
  };
}

